--
-- Triggers `boat_reservation`
--
DELIMITER $$
CREATE TRIGGER `trg_no_overlap_reservation` BEFORE INSERT ON `boat_reservation` FOR EACH ROW BEGIN
  IF EXISTS (
    SELECT 1
    FROM boat_reservation
    WHERE boat_id = NEW.boat_id
      AND boat_tour_date = NEW.boat_tour_date
      AND (
        (NEW.boat_tour_start_time BETWEEN boat_tour_start_time AND boat_tour_end_time)
        OR
        (NEW.boat_tour_end_time BETWEEN boat_tour_start_time AND boat_tour_end_time)
        OR
        (boat_tour_start_time BETWEEN NEW.boat_tour_start_time AND NEW.boat_tour_end_time)
      )
  ) THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'Overlapping reservation for this boat already exists on the selected time.';
  END IF;
END
$$
DELIMITER ;

