--
-- Triggers `room_reservation`
--
DELIMITER $$
CREATE TRIGGER `prevent_overlapping_room_reservations` BEFORE INSERT ON `room_reservation` FOR EACH ROW BEGIN
  IF EXISTS (
    SELECT 1 FROM room_reservation
    WHERE room_number = NEW.room_number
      AND (
        (NEW.check_in_date BETWEEN check_in_date AND DATE_SUB(check_out_date, INTERVAL 1 DAY)) OR
        (NEW.check_out_date BETWEEN DATE_ADD(check_in_date, INTERVAL 1 DAY) AND check_out_date) OR
        (NEW.check_in_date <= check_in_date AND NEW.check_out_date >= check_out_date)
      )
      AND status = 'Reserved'
  ) THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'This room is already reserved during the selected date range.';
  END IF;
END
$$
DELIMITER ;

